    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 84-year-old male named Thomas with end-stage metastatic lung cancer is actively dying in the hospice unit. He has severe dyspnea, using accessory muscles of respiration. Pulse oximetry shows oxygen saturation of 93% on room air. What is the most appropriate first-line pharmacological intervention to relieve his dyspnea?', '["Initiate high-flow nasal cannula oxygen at 40 L/min to raise his oxygen saturation to 100%", "Administer low-dose immediate-release morphine (oral or intravenous), as opioids are the first-line pharmacotherapy for terminal dyspnea by reducing the perception of air hunger and blunting the respiratory drive", "Initiate a continuous intravenous infusion of midazolam at a high dose to induce general anesthesia", "Prescribe oral acetazolamide to induce a metabolic acidosis and stimulate deep hyperventilation", "Administer intravenous albuterol and start an epinephrine nebulizer to dilate the pulmonary vasculature"]'::jsonb, 1, 'For the management of **dyspnea (air hunger) at the end of life**, **low-dose opioids (predominantly morphine)** are the **first-line pharmacological treatment of choice**. Opioids work by: (1) Reducing the central perception of dyspnea, (2) Blunting the ventilatory response to hypoxia and hypercapnia, and (3) Reducing anxiety and pulmonary congestion (vasodilation). **Oxygen is only indicated if the patient is hypoxic** (O2 saturation < 90-92%); studies show oxygen is no more effective than room air for non-hypoxic dyspnea. Non-pharmacological measures include a cool fan blowing air across the face. (Ref: Hazzard''s Ch. 82; UWorld Step 2 CK)'),
    (v_topic_id, 'A 72-year-old male named William with end-stage metastatic lung cancer is actively dying in the hospice unit. He has severe dyspnea, using accessory muscles of respiration. Pulse oximetry shows oxygen saturation of 93% on room air. What is the most appropriate first-line pharmacological intervention to relieve his dyspnea?', '["Administer intravenous albuterol and start an epinephrine nebulizer to dilate the pulmonary vasculature", "Administer low-dose immediate-release morphine (oral or intravenous), as opioids are the first-line pharmacotherapy for terminal dyspnea by reducing the perception of air hunger and blunting the respiratory drive", "Initiate high-flow nasal cannula oxygen at 40 L/min to raise his oxygen saturation to 100%", "Prescribe oral acetazolamide to induce a metabolic acidosis and stimulate deep hyperventilation", "Initiate a continuous intravenous infusion of midazolam at a high dose to induce general anesthesia"]'::jsonb, 1, 'For the management of **dyspnea (air hunger) at the end of life**, **low-dose opioids (predominantly morphine)** are the **first-line pharmacological treatment of choice**. Opioids work by: (1) Reducing the central perception of dyspnea, (2) Blunting the ventilatory response to hypoxia and hypercapnia, and (3) Reducing anxiety and pulmonary congestion (vasodilation). **Oxygen is only indicated if the patient is hypoxic** (O2 saturation < 90-92%); studies show oxygen is no more effective than room air for non-hypoxic dyspnea. Non-pharmacological measures include a cool fan blowing air across the face. (Ref: Hazzard''s Ch. 82; UWorld Step 2 CK)'),
